CREATE COLUMN TABLE "TEST_AP"."@BUDGET" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100), "DocEntry" INTEGER CS_INT NOT NULL , "Canceled" NVARCHAR(1) DEFAULT 'N', "Object" NVARCHAR(20), "LogInst" INTEGER CS_INT, "UserSign" INTEGER CS_INT, "Transfered" NVARCHAR(1) DEFAULT 'N', "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "UpdateTime" SMALLINT CS_INT, "DataSource" NVARCHAR(1), "U_FromDate" LONGDATE CS_LONGDATE, "U_ToDate" LONGDATE CS_LONGDATE, "U_NoOfLine" INTEGER CS_INT, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KBUDGET_IK" ON "TEST_AP"."@BUDGET" ( "DocEntry" ASC )